insert into public.guides(id,component_id,title,source_id,source_locator,engines,review_status,content) values('m50-engine-oil-and-filter','engine','Change the oil and cartridge filter on an M50 525i','bentley-e34-upload','020-8 to 020-10, Table e and Figs. 3–4; PDF 30,31,32',array['M50','M50TU']::text[],'draft','{"engines":["M50","M50TU"],"level":"Intermediate","reviewStatus":"draft","sourceChecked":true,"durationBasis":"Editorial estimate for the listed task on accessible original equipment.","slug":"m50-engine-oil-and-filter","title":"Change the oil and cartridge filter on an M50 525i","system":"engine","kind":"replacement","duration":"45–75 min","summary":"Drain the engine oil, renew the cartridge and seals, then verify oil pressure, level and leaks before driving.","applicability":"U.S. E34 525i with an installed M50 or M50TU and factory-type sump and cartridge housing. Confirm the actual drain plug and filter lid hardware. The M20 spin-on filter and aftermarket sump or housing hardware use different instructions.","source":{"id":"bentley-e34-upload","title":"BMW 5 Series (E34) Service Manual","section":"020-8 to 020-10, Table e and Figs. 3–4","pdfPages":[30,31,32]},"tools":["Correct cartridge and seal kit","New drain-plug sealing washer","Suitable engine oil","Drain pan and funnel","Sockets, torque wrench and clean lint-free cloths","Oil-resistant gloves and eye protection"],"cautions":["Use firm, level ground and immobilize the car. Never get under a car supported only by a jack. If you need to lift it, use the approved lifting and support points and the procedure in Bentley 010.","Warm oil drains quickly and can burn. Keep hands clear of the stream. Let the oil cool enough to handle safely.","If the pressure warning stays on after starting, shut the engine off immediately and resolve the cause before restarting."],"steps":[{"title":"Confirm the filter, seals and tightening values","body":"Identify the sump drain plug and the actual cartridge cover fastener before opening either. Bentley 020-9 lists 25 Nm for an original M12 sump plug and 60 Nm for M22. It lists 33 Nm for an M10/M12 filter-cover bolt and 25 Nm for a screw-on cover. These are different fasteners. Confirm the installed hardware and use its applicable instructions if it differs.","check":"The drain plug and cover each have their own confirmed value, and the filter, new washer and all applicable O-rings are on hand."},{"title":"Drain the sump and refit the plug","body":"Warm the engine briefly, switch it off and position the pan to catch the full stream. Identify the engine sump independently of the transmission. Release the plug, drain the oil and clean the mating face. Install the plug by hand with its new washer, then tighten to the confirmed value.","check":"The plug started cleanly by hand and the new washer is seated. A damaged thread or sealing face stops the job."},{"title":"Replace the cartridge and seals","body":"Remove the filter cover and lift out the old cartridge. Note the exact grooves for the cover and center-bolt seals, where fitted. Replace each old seal, lubricate the new seals with clean engine oil and seat the new element. Refit and tighten the cover using the confirmed value for that housing.","check":"No old seal remains in a groove. Each new seal sits flat and the lid is fully seated."},{"title":"Refill by the dipstick","body":"With the car level, add suitable oil in stages. Bentley lists about 5.75 L for the M50 with a filter change. Residual oil and hardware changes affect the amount needed. Check the dipstick after the oil settles and leave the reading within the marked range before starting.","check":"Filler cap and dipstick are in place and the level is in range."},{"title":"Check pressure, leaks and final level","body":"Start from the driver’s seat and watch the oil pressure warning. Stop immediately if it stays on. Once normal pressure is indicated, check for fresh leaks from a safe position. Switch off, allow the oil to settle, recheck on level ground and correct the level in small amounts. Recycle the used oil and filter at an appropriate collection point.","check":"Warning clears, drain and housing are dry, and the final dipstick reading is in range."}]}'::jsonb) on conflict do nothing;
insert into public.guides(id,component_id,title,source_id,source_locator,engines,review_status,content) values('factory-halogen-headlight-bulb','electrical','Replace a factory twist-lock halogen headlight bulb','bentley-e34-upload','630-1 to 630-2, Figs. 1–2; 121-1; PDF 163,407,408',array['M20','M30','M50','M50TU','M60']::text[],'draft','{"engines":["M20","M30","M50","M50TU","M60"],"level":"Beginner","reviewStatus":"draft","sourceChecked":true,"durationBasis":"Editorial estimate for the listed task on accessible original equipment.","slug":"factory-halogen-headlight-bulb","title":"Replace a factory twist-lock halogen headlight bulb","system":"electrical","kind":"replacement","duration":"15–30 min","summary":"Identify the failed beam, access the rear of the lamp and verify the replacement is fully seated before testing.","applicability":"Source-matching factory U.S. halogen housings with the rear quarter-turn bulb mount shown in Bentley 630. Check the actual lamp and bulb specification. Other retention systems and HID or LED conversions need their own procedure.","source":{"id":"bentley-e34-upload","title":"BMW 5 Series (E34) Service Manual","section":"630-1 to 630-2, Figs. 1–2; 121-1","pdfPages":[163,407,408]},"tools":["Correct halogen bulb for the installed housing","Screwdriver for the rear cover","Clean gloves and a light","Tool for the negative battery terminal"],"cautions":["Turn off the lamps and ignition and let the bulb cool. Follow Bentley 121 for safe negative-battery cable isolation and any radio-code preparation.","Handle halogen bulbs by their base. Do not use this method on high-voltage retrofit lighting or force a mismatched socket."],"steps":[{"title":"Identify the lamp and verify the bulb","body":"Identify which side and beam failed before isolating the battery. Confirm the replacement specification and connector against the housing and vehicle information.","check":"You have the correct replacement for that position and the electrical supply is isolated."},{"title":"Open rear access","body":"Under the bonnet, remove the protective cover behind the headlight. On the driver’s side, move the alternator cooling duct first if it blocks the cover. Keep the cover screws and duct hardware together.","check":"The rear bulb base is accessible without disturbing the headlamp adjusters."},{"title":"Release the old bulb and seat the new one","body":"Looking at the lamp from behind, turn the original bulb base counterclockwise a quarter turn. Withdraw it and release the connector at its latch. Compare the old and new tabs. Reconnect the replacement, align the tabs with the housing slots and lock it with a clockwise quarter turn.","check":"The base sits flush, turns to its stop and has no play. The connector is latched."},{"title":"Restore the covers and verify the beam","body":"Refit the protective cover and any duct removed. Restore the battery connection per the applicable procedure. Test low and high beams, watch for a bulb warning and compare the projected pattern with the opposite side. An abnormal pattern or recurring warning needs inspection before driving in low visibility.","check":"Both beams operate as expected, covers are secure and the repaired bulb does not sit crooked."}]}'::jsonb) on conflict do nothing;
insert into public.guides(id,component_id,title,source_id,source_locator,engines,review_status,content) values('sedan-tail-lamp-bulb','electrical','Replace a body-mounted tail lamp bulb on an E34 Sedan','bentley-e34-upload','630-1, electrical precautions; 630-4, Fig. 10; 121-1; PDF 163,407,410',array['M20','M30','M50','M50TU','M60']::text[],'draft','{"engines":["M20","M30","M50","M50TU","M60"],"level":"Beginner","reviewStatus":"draft","sourceChecked":true,"durationBasis":"Editorial estimate for the listed task on accessible original equipment.","slug":"sedan-tail-lamp-bulb","title":"Replace a body-mounted tail lamp bulb on an E34 Sedan","system":"electrical","kind":"replacement","duration":"10–20 min","summary":"Access the original twist-lock holder behind the trunk liner and verify the replacement lamp function.","applicability":"Bentley-covered U.S. E34 Sedan with the body-mounted rear lamp and removable quarter-turn socket shown in group 630. Excludes Touring, trunk-lid and center high-mounted lamp assemblies.","source":{"id":"bentley-e34-upload","title":"BMW 5 Series (E34) Service Manual","section":"630-1, electrical precautions; 630-4, Fig. 10; 121-1","pdfPages":[163,407,410]},"tools":["Replacement bulb matched to the position and rating","Light","Tool for the negative battery terminal"],"cautions":["Switch off the lamps and ignition, allow the bulb to cool and isolate the negative battery terminal per the vehicle procedure.","Stop for melted contacts, water intrusion or brittle wiring. A new bulb will not repair a damaged socket."],"steps":[{"title":"Identify the failed function","body":"With the car parked, confirm whether the tail, brake or another rear lighting function is affected. Match the bulb’s base, contact count and rating to that position before fitting a replacement.","check":"The bulb and lamp position are identified, and power is isolated before disassembly."},{"title":"Reach and remove the holder","body":"Release the side liner retainer in the trunk and pull the liner aside. Grip the holder rather than the wires. Turn the holder a quarter turn to unlock it, then pull it out of the body-mounted lens.","check":"The correct holder is free and the wiring and lens are undamaged."},{"title":"Install the bulb and lock the holder","body":"Press the old bulb gently into its bayonet socket and turn it counterclockwise to release it. Match the new bulb pins to the socket slots, press and turn it into lock. Refit the holder and secure the liner.","check":"The bulb stays seated and the holder locks without forcing it."},{"title":"Verify the lighting","body":"Restore the battery connection and test the affected function. Use a helper or a safe reflection for brake lamps. Check the other functions on that housing and record any remaining warning.","check":"The repaired lamp and the other affected housing functions work before the car is driven."}]}'::jsonb) on conflict do nothing;
insert into public.guides(id,component_id,title,source_id,source_locator,engines,review_status,content) values('front-door-window-dropped-inspection','body','Check a front door window that dropped or sits crooked','bentley-e34-upload','512-1, Figs. 1–2 and chapter contents; PDF 353',array['M20','M30','M50','M50TU','M60']::text[],'draft','{"engines":["M20","M30","M50","M50TU","M60"],"level":"Beginner","reviewStatus":"draft","sourceChecked":true,"durationBasis":"Editorial estimate for the listed task on accessible original equipment.","slug":"front-door-window-dropped-inspection","title":"Check a front door window that dropped or sits crooked","system":"body","kind":"inspection","duration":"5–10 min","summary":"Record the glass position and symptoms without cycling a loose window. Identify the right source section for slides, regulator or motor work.","applicability":"Front door glass on Bentley-covered U.S. E34s. This check uses external observations only. Removing the glass, liner or regulator requires a separate procedure and support for the glass.","source":{"id":"bentley-e34-upload","title":"BMW 5 Series (E34) Service Manual","section":"512-1, Figs. 1–2 and chapter contents","pdfPages":[353]},"tools":["Light","Camera or service log"],"cautions":["Leave the window switch off if the glass is loose, tilted or jammed. Keep fingers out of the slot and regulator path.","Broken or unsupported glass requires safe handling and support before the door is opened up. Do not slam the door to test it."],"steps":[{"title":"Record where the glass stopped","body":"With the ignition off, record which door is affected and whether the glass is below the seal, tilted or loose. Note any click, motor noise or slow movement that you heard before the failure, without repeating the test on a loose window.","check":"A photo and description identify the door and glass position without operating the mechanism."},{"title":"Separate the glass support from the drive","body":"The manual shows two slides with retaining clips at the lifting-arm connections on the front glass. A loose window is reason to inspect these connections and guides once the glass is safely supported. A silent drive can also require an electrical check. The symptom alone does not identify a failed part.","check":"The report keeps glass support, regulator movement and motor operation separate."},{"title":"Choose the next source and protect the car","body":"Use chapter 512 for front glass and regulator procedures and chapter 411 for door trim access. Arrange safe support or repair if the glass cannot be secured. Share the exact door, symptoms and prior work before ordering a slide, regulator or motor.","check":"The next step identifies what needs inspection and which manual group applies."}]}'::jsonb) on conflict do nothing;
